#!/usr/bin/env bash
# СУДИТ: scripts/defect-class-carriers.py scripts/knowledge-independence.py
# probe_D447.sh — проба пункта D447: `scripts/defect-class-carriers.py` падает Traceback'ом,
#                 когда файл числится в git (`git ls-files`), но удалён с диска без `git rm`
#                 / `git add -u`. Род не заведён на этот файл (реестр не подтверждает ни
#                 одной буквы) — пометка «род B» в SESSION.md тематическая, здесь не
#                 повторяется.
# Результат: на файле, удалённом с диска без обновления индекса, механизм не роняет
#            Traceback — НАЗЫВАЕТ пропущенный файл в stderr и продолжает работу, а отчёт по
#            ОСТАЛЬНЫМ файлам остаётся тем же, что на целом дереве.
# Проверка результата: bash hooks/tests/fixtures/probe_D447.sh даёт 0
#
# Коды: 0 — желаемое поведение соблюдено; 1 — дефект наблюдён; 2 — рамка не собралась.
#
# СУДЯТСЯ ТРИ ПРИЗНАКА, А НЕ ОДИН, и каждый заведён по ПОЗЕЛЕНЕВШЕЙ подделке скептика.
# Первая редакция судила только «нет Traceback» — её позеленили тихий фильтр без единого
# слова в stderr, глобальная подмена `Path.read_text`, глотающая любой OSError, и
# `try/except` вокруг вызывающих, схлопывающий род в «носителей: 0». Вторая редакция
# добавила имя файла в stderr и код возврата 3 — её позеленила починка, ВЫБРАСЫВАЮЩАЯ весь
# вход (`tracked()` отдаёт пустой список, отчёт обнуляется: «Носителей A: 0, B: 0…»).
# Поэтому здесь судится: (1) нет Traceback, (2) пропущенный файл НАЗВАН по имени в stderr,
# (3) отчёт по остальным файлам ПОБАЙТНО тот же, что на целом дереве. Код возврата не
# судится вовсе: он у прибора занят тремя смыслами (0 род пуст, 1 носители есть, 2 признак
# не заведён), и четвёртый ломал троих читателей — см. шапку `tracked()` в механизме.
# Механизм под судом собирается в СВОЁМ временном проекте: ROOT в defect-class-carriers.py
# берётся из __file__, а не из CLAUDSOUL_REPO (в отличие от project-graph.py), поэтому
# копия кладётся в песочницу и зовётся ОТТУДА — приём как у probe_D427.sh. Живой
# ~/.claude/hooks/state не читается: STATE_DIR указывает в песочницу, кэш кладётся заново
# при каждом запуске (DCC_NO_CACHE=1), сеть и модель не зовутся.
set -uo pipefail
ROOT="$(cd "$(dirname "$0")/../../.." && pwd -P)"
MECH="${CLAUDSOUL_REPO:-$ROOT}"
[ -f "$MECH/scripts/defect-class-carriers.py" ] || { echo "probe_D447: нет $MECH/scripts/defect-class-carriers.py" >&2; exit 2; }
command -v git >/dev/null 2>&1 || { echo "probe_D447: нет git" >&2; exit 2; }
command -v python3 >/dev/null 2>&1 || { echo "probe_D447: нет python3" >&2; exit 2; }
T=$(cd "$(mktemp -d)" && pwd -P) || { echo "probe_D447: нет временного каталога" >&2; exit 2; }
trap 'rm -rf "$T"' EXIT
P="$T/proj"; mkdir -p "$P/scripts" "$T/state"
cp "$MECH/scripts/defect-class-carriers.py" "$P/scripts/" || { echo "probe_D447: копия механизма не удалась" >&2; exit 2; }
# install.sh читается carriers_j() безусловно (:1842) — без него ЗДОРОВЫЙ прогон падал бы
# по СОВСЕМ другой причине, и контраст перестал бы отличаться ровно удалённым файлом.
printf '' > "$P/install.sh"
printf 'x = 1\n' > "$P/scripts/dummy.py"
# Песочнице нужен ХОТЬ ОДИН настоящий носитель, иначе отчёт в ней сплошь нулевой и сравнение
# «до/после» ничего не различает: подделка, выбрасывающая весь вход, даёт те же нули.
# `knowledge-independence.py` — носитель рода A на живом дереве (извлечений 7, разборов 1).
cp "$MECH/scripts/knowledge-independence.py" "$P/scripts/" 2>/dev/null \
    || { echo "probe_D447: нет scripts/knowledge-independence.py — носителя для песочницы" >&2; exit 2; }
( cd "$P" && git init -q . && git add -A \
    && git -c user.email=p@p -c user.name=p commit -qm i ) >/dev/null 2>&1 \
    || { echo "probe_D447: git-песочница не поднялась" >&2; exit 2; }
grep -q '^scripts/dummy\.py$' <<< "$(git -C "$P" ls-files)" \
    || { echo "probe_D447: git ls-files не видит dummy.py — фундамента нет" >&2; exit 2; }

# Полный отчёт, а не один род: сравнение «до/после» судит СЧЁТЧИКИ ВСЕХ родов и строку
# «Прожарено механизмов», а под `--genus G` подделка, обнулившая вход, осталась бы
# неотличимой — род G в песочнице пуст и до, и после.
run() { ( cd "$P" && STATE_DIR="$T/state" DCC_NO_CACHE=1 python3 scripts/defect-class-carriers.py ) 2>"$T/err"; }

# Положительный контроль: все файлы на месте — механизм не падает и печатает что-то в stdout.
OUT=$(run); RC=$?
ERR=$(cat "$T/err" 2>/dev/null || true)
if grep -q 'Traceback' <<< "$ERR"; then
    echo "probe_D447: контроль — на целом дереве уже Traceback (код $RC): $(head -1 <<< "$ERR")" >&2
    exit 2
fi
[ -n "$OUT" ] || { echo "probe_D447: контроль — здоровый прогон дал пустой stdout (код $RC) — рамка не собралась" >&2; exit 2; }
# Тот же контроль в обратную сторону: на ЦЕЛОМ дереве о пропуске не говорится — иначе
# «починка», объявляющая пропуск ВСЕГДА, прошла бы судом ниже.
grep -q 'не на диске' <<< "$ERR" && { echo "probe_D447: контроль — на целом дереве уже говорится о пропуске: $(grep -m1 'не на диске' <<< "$ERR")" >&2; exit 2; }
# Отчёт целого дерева сохраняется ЭТАЛОНОМ: судить «не искажён» можно только против него.
BASE="$OUT"; BASE_RC="$RC"
# Рамка обязана уметь различать: в эталоне есть хотя бы один НЕнулевой счётчик рода.
grep -qE 'Носителей [A-Z]: [1-9]' <<< "$BASE" || grep -qE 'Носителей .*[A-Z]: [1-9]' <<< "$BASE" \
    || { echo "probe_D447: контроль — отчёт песочницы сплошь нулевой, сравнение ничего не различит" >&2; exit 2; }

# Суд: dummy.py удалён с диска, но НЕ из индекса (нет git rm, нет git add -u) — файл
# по-прежнему числится в `git ls-files`, механизм обязан не падать.
rm -f "$P/scripts/dummy.py"
grep -q '^scripts/dummy\.py$' <<< "$(git -C "$P" ls-files)" \
    || { echo "probe_D447: dummy.py пропал из индекса — сценарий не воспроизведён" >&2; exit 2; }
[ ! -e "$P/scripts/dummy.py" ] || { echo "probe_D447: dummy.py не удалён с диска" >&2; exit 2; }

OUT=$(run); RC=$?
ERR=$(cat "$T/err" 2>/dev/null || true)
# Решает Traceback САМ ПО СЕБЕ — пустой stdout только упоминается рядом, как вторая
# улика. Составное условие («и пустой stdout») ловилось бы формой: патч, который не
# трогает tracked(), а лишь печатает байт в stdout ДО падения, даёт непустой $OUT при
# живом FileNotFoundError — и должен остаться дефектом, а не мнимой починкой.
if grep -q 'Traceback' <<< "$ERR"; then
    _extra="stdout непуст: [$OUT]"; [ -z "$OUT" ] && _extra="stdout пуст (доп. улика)"
    echo "probe_D447: дефект — файл в git есть, на диске нет, Traceback: $(grep -m1 'Error' <<< "$ERR") ($_extra)" >&2
    exit 1
fi
[ -n "$OUT" ] || { echo "probe_D447: рамка не собралась — нет Traceback, но и вывода нет (rc=$RC)" >&2; exit 2; }
# Второй признак: пропуск НАЗВАН, и назван именем файла, а не общей фразой.
grep -q 'scripts/dummy\.py' <<< "$ERR" || {
    echo "probe_D447: дефект — Traceback снят, но пропущенный файл не назван в stderr (rc=$RC): [${ERR:-пусто}]" >&2
    exit 1; }
# Третий признак: отчёт по ОСТАЛЬНЫМ файлам тот же, что был. Удалённый `dummy.py` носителем
# ни одного рода не является, поэтому здоровая починка обязана дать побайтно тот же отчёт;
# «починка», выбрасывающая весь вход, обнуляет счётчики родов и краснеет здесь.
if [ "$OUT" != "$BASE" ]; then
    echo "probe_D447: дефект — пропуск одного файла изменил отчёт по остальным (было/стало):" >&2
    diff <(printf '%s\n' "$BASE") <(printf '%s\n' "$OUT") | head -6 >&2
    exit 1
fi
[ "$RC" = "$BASE_RC" ] || {
    echo "probe_D447: дефект — отчёт тот же, а код возврата сменился ($BASE_RC → $RC)" >&2; exit 1; }
exit 0
